# Privacy Policy text (published version). Each section: (label, [paragraphs]). Paragraphs are Elementor
# "escaped-html": inline <strong>, <a>, <br> only; & written as &amp;.
EFFECTIVE = 'October 27, 2026'
HERO_EYEBROW = 'Legal'
HERO_TITLE = 'Privacy Policy'
HERO_LEAD = ('How Axiom Systems collects, uses and protects information when you visit our website, contact us or use '
             'our services.<br><strong>Effective date:</strong> ' + EFFECTIVE)

SECTIONS = [
 ('Overview', [
  'This Privacy Policy explains how Axiom Systems (&#8220;Axiom Systems,&#8221; &#8220;we,&#8221; &#8220;us&#8221; or &#8220;our&#8221;) collects, uses and shares information when you visit <a href="https://axiomsystems.systems/"><u>axiomsystems.systems</u></a> (the &#8220;Website&#8221;), contact us, or use our services. Our services include website-as-a-service, web design, website hosting and maintenance, Google Ads management, lead capture, CRM automation, appointment scheduling, automated follow-ups and review request systems.',
  'Our services are offered to businesses in the United States. By using the Website or contacting us, you acknowledge the practices described in this policy.',
 ]),
 ('1. Information we collect', [
  '<strong>Information you provide.</strong> When you submit our Get Started form, we collect your name, business name, email address, phone number, current website address (optional), what you tell us about your business, and the plan or service you were viewing when you contacted us. When you use the chat widget on our Website, we collect the name, contact details and messages you enter. We also collect information you share when you call, text or email us.',
  '<strong>Information from clients.</strong> If you become a client, we collect the business, billing and account information needed to provide our services, along with the content, images and other materials you give us for your website, campaigns and automations.',
  '<strong>Information collected automatically.</strong> When you visit the Website, we and our service providers automatically collect technical information such as your IP address, browser and device type, the pages you view, the page that referred you, and the date and time of your visit. When you submit our form, your IP address and browser information are stored with your submission to help us prevent spam and abuse. See &#8220;Cookies and analytics&#8221; below.',
  '<strong>Information from third parties.</strong> We may receive information from advertising platforms such as Google (for example, the details you submit in a Google Ads lead form, or information about which ad led to your visit) and from people who refer you to us.',
 ]),
 ('2. How we use information', [
  'We use the information we collect to respond to your inquiries and questions; to schedule and confirm consultations and appointments; to provide, manage and support our services; to manage our client relationships, including billing and account communications; to send marketing communications where permitted by law or where you have agreed to receive them; to measure and improve our Website and our advertising; to protect our Website, our business and our users against spam, fraud and abuse; and to comply with legal obligations and enforce our agreements.',
 ]),
 ('3. Google Ads and lead forms', [
  'We advertise our services with Google Ads. When you visit our Website after clicking one of our ads, Google may use cookies to measure the ad&#8217;s performance. When you successfully submit our Get Started form, our Website reports a conversion to Google Ads so we can see which ads produce inquiries. This report contains a reference number for the submission; it does not include the answers you entered in the form.',
  'If we run ads that include a Google lead form and you submit it, Google provides the information you enter (such as your name, email address and phone number) to us so we can respond to your request, and we add it to our CRM. Google&#8217;s collection and use of information is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noopener"><u>Google Privacy Policy</u></a>.',
 ]),
 ('4. CRM and automation', [
  'Inquiries from our Get Started form are saved on our Website, emailed to our team, and transferred to our customer relationship management (CRM) system, which is built on the GoHighLevel (LeadConnector) platform. Conversations started in our chat widget are handled in the same CRM. In the CRM we keep your contact details, notes about your inquiry, the status of your inquiry in our sales process, appointments, and the history of our communications with you.',
  'We use automations in the CRM to respond to new inquiries, send follow-up messages, send appointment confirmations and reminders, and, for clients who have used our services, send requests to review our business.',
  '<strong>Information we handle for our clients.</strong> When we build or manage websites, CRMs, automations or advertising for a client, we may process information about that client&#8217;s own customers and leads on the client&#8217;s behalf and according to the client&#8217;s instructions. The client is responsible for its own privacy notices and for obtaining any consent required for its communications. Questions about that information should be directed to the client.',
 ]),
 ('5. Text messages (SMS)', [
  '<strong>How consent is obtained.</strong> When you give us your mobile phone number and ask us to contact you, for example through our Get Started form, our chat widget, or by texting or calling us, you agree that Axiom Systems may send you text messages related to your request. We send marketing text messages only to people who have agreed to receive them. Consent to receive marketing text messages is not a condition of purchasing any service.',
  '<strong>Messages we send.</strong> Text messages may include responses to your inquiry, follow-up about the services you asked about, scheduling, appointment confirmations and reminders, and, for clients, service and account updates. Message frequency varies. Message and data rates may apply.',
  '<strong>Opting out and help.</strong> You can opt out at any time by replying <strong>STOP</strong> to any message. After you opt out, you may receive one message confirming your request, and we will not send further text messages unless you opt in again. Reply <strong>HELP</strong> for help, or call us at <a href="tel:+17275917527"><u>(727) 591-7527</u></a>. Wireless carriers are not liable for delayed or undelivered messages.',
  '<strong>No sharing of mobile information.</strong> We do not sell, rent or share mobile phone numbers, SMS opt-in information or SMS consent with third parties or affiliates for their own marketing or promotional purposes. Text messaging originator opt-in data and consent will not be shared with any third parties, except service providers that help us deliver messages on our behalf.',
 ]),
 ('6. Email', [
  'We send emails to respond to your inquiry, schedule appointments and provide our services. If we send you marketing emails, you can unsubscribe at any time using the link in the email or by contacting us. If you are a client, we may continue to send service and account emails while you use our services.',
 ]),
 ('7. Cookies and analytics', [
  'Our Website uses cookies and similar technologies, including:',
  '<strong>Google Analytics</strong>, to understand how visitors use our Website.<br><strong>Google Ads conversion tracking</strong>, to measure whether our ads lead to inquiries.<br><strong>Jetpack Stats and WooCommerce Analytics</strong> (Automattic), for website statistics.<br><strong>WooCommerce visitor-source cookies</strong>, which record how you arrived at our Website (for example, a search engine, referral or campaign link).<br><strong>Security cookies</strong> set through our hosting provider&#8217;s network (Cloudflare) to distinguish people from automated traffic.<br><strong>Our LeadConnector chat widget</strong>, which may store information in your browser to keep your chat session working.<br><strong>Google Fonts</strong>, which loads our typefaces from Google&#8217;s servers.',
  'You can block or delete cookies in your browser settings; some features may not work as intended if you do. You can manage Google ad personalization in <a href="https://adssettings.google.com" target="_blank" rel="noopener"><u>Google&#8217;s Ad Settings</u></a> and opt out of Google Analytics with the <a href="https://tools.google.com/dlpage/gaoptout" target="_blank" rel="noopener"><u>Google Analytics opt-out browser add-on</u></a>. For visitors in the European Economic Area, the United Kingdom and Switzerland, our Google tags use Google Consent Mode, which by default does not use advertising or analytics cookies until consent is given. Our Website does not currently respond to &#8220;Do Not Track&#8221; browser signals.',
 ]),
 ('8. Service providers and sharing', [
  'We do not sell your personal information for money. We share information only as described in this policy, including with service providers that process it on our behalf and under their own privacy and security obligations: our website hosting provider (Kinsta, delivered through Cloudflare&#8217;s network); our website platform and its plugins (WordPress, and Jetpack by Automattic for forms and statistics); our CRM and communications platform (GoHighLevel / LeadConnector) and the telecommunications and email providers used to deliver our messages; our business email provider; Google (Analytics, Ads and Fonts); and the payment processors we use to bill clients.',
  'We may also disclose information when required by law or legal process; to protect the rights, property and safety of Axiom Systems, our clients or others; in connection with a merger, acquisition or sale of all or part of our business; or with your direction or consent.',
 ]),
 ('9. Data retention and security', [
  'We keep personal information for as long as reasonably necessary for the purposes described in this policy, including responding to your inquiry, providing our services, maintaining business records, complying with legal, tax and accounting obligations, resolving disputes, and keeping records of consent and opt-out requests. When information is no longer needed, we delete it or keep it in a form that no longer identifies you.',
  'We use reasonable administrative and technical safeguards designed to protect personal information, such as encrypted (HTTPS) connections to our Website and limiting access to the people and service providers who need it. No method of transmission or storage is completely secure, and we cannot guarantee absolute security.',
 ]),
 ('10. Your privacy rights', [
  'Depending on where you live and the laws that apply to us, you may have the right to request access to the personal information we hold about you, to correct it, to delete it, to receive a copy of it, or to opt out of certain uses, such as targeted advertising. You can always opt out of marketing messages as described above.',
  'To make a request, contact us using the details below. We will verify your request and respond as required by applicable law. We will not discriminate against you for exercising your privacy rights.',
 ]),
 ('11. Children&#8217;s privacy', [
  'Our Website and services are intended for businesses and adults. They are not directed to children under 13, and we do not knowingly collect personal information from children. If you believe a child has provided us with personal information, please contact us and we will delete it.',
 ]),
 ('12. Changes to this policy', [
  'We may update this Privacy Policy from time to time. When we do, we will post the updated policy on this page and change the effective date above. If we make material changes, we will provide additional notice, such as a notice on our Website or an email to clients.',
 ]),
 ('13. Contact us', [
  'If you have questions about this Privacy Policy or want to exercise your privacy rights, contact us:',
  '<strong>Axiom Systems</strong><br>Website: <a href="https://axiomsystems.systems/"><u>axiomsystems.systems</u></a><br>Phone: <a href="tel:+17275917527"><u>(727) 591-7527</u></a><br>Email: <a href="mailto:axiom.systems.co@gmail.com"><u>axiom.systems.co@gmail.com</u></a>',
 ]),
]
